import 'package:flutter/material.dart';import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';class PregnancyTrackerCard extends StatelessWidget{final PregnancyTracker? tracker;final Color accentColor;final VoidCallback? onTap;const PregnancyTrackerCard({super.key,this.tracker,this.accentColor=const Color(0xFFE91E63),this.onTap});@override Widget build(BuildContext c){final w=tracker?.currentWeek??0;final progress=(w/40).clamp(0.0,1.0);return Card(child:InkWell(onTap:onTap,borderRadius:BorderRadius.circular(16),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Icon(Icons.pregnant_woman,color:accentColor,size:30),const SizedBox(width:10),const Expanded(child:Text('متابعة الحمل',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17))),Text('الأسبوع $w',style:TextStyle(color:accentColor,fontWeight:FontWeight.w800))]),const SizedBox(height:12),LinearProgressIndicator(value:progress,minHeight:8,borderRadius:BorderRadius.circular(8),color:accentColor),const SizedBox(height:8),Text(w==0?'أضف بيانات الحمل لبدء المتابعة':'الثلث ${w<=13?'الأول':w<=27?'الثاني':'الثالث'} • ${tracker?.dueDate==null?'موعد الولادة غير محدد':'الولادة المتوقعة: ${tracker!.dueDate!.day}/${tracker!.dueDate!.month}'}',style:TextStyle(color:Theme.of(c).brightness==Brightness.dark?Colors.grey[300]:Colors.grey[700]))]))));}}
